for (const [title, matches] of groups) {
  const actions = [...remaining].filter(matches).sort();
  if (!actions.length) continue;
  lines.push(`### ${title} (${actions.length})`, '');
  for (const action of actions) {
    remaining.delete(action);
    const route = audit.routes[action];
    const probes = checks.filter(([name, source]) => source.includes(`'${action}'`) || source.includes(`"${action}"`) ||
      route.status === 'unsupported' && name === 'test_offline_recovery.cjs')
      .map(([name]) => `[${name}](../tools/${name})`).join(', ') || 'No literal probe found';
    const nativeEvidence=route.nativeEvidence ?? (/MuMu|Earlier native proof|Native isolated/.test(route.gap) ? 'limited, see audit' : 'not recorded in audit');
    lines.push(`- [ ] \`${action}\` — ${route.status}; earlier native evidence: ${nativeEvidence}; probes: ${probes}.`);
  }
  lines.push('');
}
if (remaining.size) throw new Error('Incomplete packet checklist');
